#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_process_guess_correct_guess_guesses_size_less_than_25(void) {
    const char *word = "apple";
    char guess = 'a';

    // Create temporary struct matching process_guess expectations
    struct {
        char *current_word;
        int size;
        char guesses[25];
        int guesses_size;
        int incorrect;
        char hidden[6];
    } temp_game;

    // Initialize struct
    temp_game.current_word = (char*)word;
    temp_game.size = strlen(word);
    temp_game.guesses_size = 0;
    temp_game.incorrect = 0;
    for (int i = 0; i < temp_game.size; i++) {
        temp_game.hidden[i] = '_';
    }
    temp_game.hidden[temp_game.size] = '\0';

    TEST_ASSERT_EQUAL_INT(0, temp_game.guesses_size);
    TEST_ASSERT_EQUAL_INT(0, temp_game.incorrect);

    int result = process_guess((struct game_instance*)&temp_game, guess);

    TEST_ASSERT_EQUAL_INT(1, result);
    TEST_ASSERT_EQUAL_INT(1, temp_game.guesses_size);
    TEST_ASSERT_EQUAL_INT('a', temp_game.guesses[0]);
    TEST_ASSERT_EQUAL_INT(0, temp_game.incorrect);
    TEST_ASSERT_EQUAL_INT('a', temp_game.hidden[0]);
    TEST_ASSERT_EQUAL_INT('_', temp_game.hidden[1]);
    TEST_ASSERT_EQUAL_INT('_', temp_game.hidden[2]);
    TEST_ASSERT_EQUAL_INT('_', temp_game.hidden[3]);
    TEST_ASSERT_EQUAL_INT('_', temp_game.hidden[4]);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_process_guess_correct_guess_guesses_size_less_than_25);
    return UNITY_END();
}

